"use client";

import { useEffect, useState, useRef } from "react";
import { useTheme } from "@/components/ThemeContext";
import ShortcutsModal from "./ShortcutsModal";

export default function GlobalKeyboardShortcuts() {
  const [isOpen, setIsOpen] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const { theme, themeDefinition, toggleTheme } = useTheme();
  const keyboardToggleRef = useRef(false);

  useEffect(() => {
    if (keyboardToggleRef.current && theme !== undefined) {
      setAnnouncement(`${themeDefinition?.name ?? "Theme"} enabled`);
    }
    keyboardToggleRef.current = false;
  }, [theme, themeDefinition]);

  useEffect(() => {
    const handleOpenShortcuts = () => {
      setIsOpen(true);
    };
    window.addEventListener("openShortcuts", handleOpenShortcuts);
    return () => {
      window.removeEventListener("openShortcuts", handleOpenShortcuts);
    };
  }, []);

  useEffect(() => {
    let gPressed = false;

    const handleKeyDown = (e: KeyboardEvent) => {
      const activeElement = document.activeElement;
      if (activeElement) {
        const tagName = activeElement.tagName.toLowerCase();
        if (tagName === "input" || tagName === "textarea" || tagName === "select") return;
        if (activeElement.getAttribute("contenteditable") === "true") return;
      }

      // Show shortcuts modal
      if (e.key === "?") {
        setIsOpen(true);
        e.preventDefault();
        return;
      }

      // Alt+T / Option+T to toggle theme
      if (e.altKey && e.key.toLowerCase() === "t") {
        keyboardToggleRef.current = true;
        toggleTheme();
        e.preventDefault();
        return;
      }

      // Toggle chart
      if (e.key.toLowerCase() === "b") {
        window.dispatchEvent(new Event("toggleChart"));
        e.preventDefault();
        return;
      }

      // G key handling (chord detection)
      if (e.key.toLowerCase() === "g") {
        gPressed = true;
        setTimeout(() => {
          gPressed = false;
        }, 1000);
        e.preventDefault();
        return;
      }

      // G + D -> Dashboard
      if (gPressed && e.key.toLowerCase() === "d") {
        window.location.href = "/dashboard";
        e.preventDefault();
        return;
      }

      // G + P -> Goals (scroll to goals section)
      if (gPressed && e.key.toLowerCase() === "p") {
        const goalSection = document.getElementById("goals-section");
        if (goalSection) {
          goalSection.scrollIntoView({ behavior: "smooth", block: "center" });
        }
        e.preventDefault();
        return;
      }

      // ESC -> close modal
      if (e.key === "Escape") {
        setIsOpen(false);
        window.dispatchEvent(new Event("closeModal"));
        e.preventDefault();
        return;
      }

      // Reload page
      if (e.key.toLowerCase() === "r") {
        window.location.reload();
        e.preventDefault();
        return;
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [toggleTheme]);

  return (
    <>
      <div aria-live="polite" className="sr-only">
        {announcement}
      </div>
      <ShortcutsModal isOpen={isOpen} onClose={() => setIsOpen(false)} />
    </>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { signOut } from "next-auth/react";
import { useAccount } from "@/components/AccountContext";
import {
  CartesianGrid,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

interface PRReviewTrendPoint {
  weekStart: string;
  label: string;
  avgReviewDays: number | null;
  mergedCount: number;
}

interface PRReviewTrendResponse {
  weeks: PRReviewTrendPoint[];
}

function formatDays(value: number | null | undefined) {
  if (value === null || value === undefined) return "No data";
  if (value < 1) return `${(value * 24).toFixed(1)}h`;
  return `${value.toFixed(2)}d`;
}

function CustomTooltip({
  active,
  payload,
  label,
}: {
  active?: boolean;
  payload?: any[];
  label?: string;
}) {
  if (!active || !payload?.length) return null;

  const point = payload[0]?.payload as PRReviewTrendPoint;

  return (
    <div className="rounded-lg border border-[var(--border)] bg-[var(--card)] px-4 py-3 shadow-lg">
      <p className="text-sm font-semibold text-[var(--card-foreground)]">
        {label}
      </p>

      {point.avgReviewDays === null ? (
        <p className="mt-1 text-sm text-[var(--muted-foreground)]">
          No merged PRs this week
        </p>
      ) : (
        <>
          <p className="mt-1 text-sm text-[var(--muted-foreground)]">
            Avg merge time:{" "}
            <span className="font-semibold text-[var(--card-foreground)]">
              {formatDays(point.avgReviewDays)}
            </span>
          </p>
          <p className="mt-1 text-xs text-[var(--muted-foreground)]">
            Based on {point.mergedCount} merged PR
            {point.mergedCount === 1 ? "" : "s"}
          </p>
        </>
      )}
    </div>
  );
}

export default function PRReviewTrendChart() {
  const { selectedAccount } = useAccount();

  const [data, setData] = useState<PRReviewTrendPoint[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [githubAuthInvalid, setGithubAuthInvalid] = useState(false);

  const fetchTrend = useCallback(() => {
    setLoading(true);
    setError(null);
    setGithubAuthInvalid(false);

    const url =
      selectedAccount !== null
        ? `/api/metrics/pr-review-time?accountId=${encodeURIComponent(
            selectedAccount
          )}`
        : "/api/metrics/pr-review-time";

    fetch(url)
      .then(async (r) => {
        const body = await r.json();
        if (body?.error === "token_expired") {
          setGithubAuthInvalid(true);
          return null;
        }
        if (!r.ok) throw new Error("API error");
        return body as PRReviewTrendResponse;
      })
      .then((res) => {
        if (!res) return;
        setData(res.weeks ?? []);
      })
      .catch(() => {
        setError(
          "We couldn't load your PR review trend right now. Please try again."
        );
      })
      .finally(() => setLoading(false));
  }, [selectedAccount]);

  useEffect(() => {
    fetchTrend();
  }, [fetchTrend]);

  const stats = useMemo(() => {
    const validWeeks = data.filter((week) => week.avgReviewDays !== null);
    const totalMerged = data.reduce((sum, week) => sum + week.mergedCount, 0);

    const overallAvg =
      validWeeks.length > 0
        ? validWeeks.reduce(
            (sum, week) => sum + (week.avgReviewDays ?? 0),
            0
          ) / validWeeks.length
        : null;

    const latestValid = [...data]
      .reverse()
      .find((week) => week.avgReviewDays !== null);

    const previousValid = [...data]
      .reverse()
      .filter((week) => week.avgReviewDays !== null)[1];

    let trendText = "Not enough data";
    if (latestValid && previousValid) {
      const diff =
        (latestValid.avgReviewDays ?? 0) - (previousValid.avgReviewDays ?? 0);

      if (Math.abs(diff) < 0.01) {
        trendText = "No major change";
      } else if (diff < 0) {
        trendText = `${Math.abs(diff).toFixed(2)}d faster`;
      } else {
        trendText = `${diff.toFixed(2)}d slower`;
      }
    }

    return {
      totalMerged,
      overallAvg,
      latestAvg: latestValid?.avgReviewDays ?? null,
      trendText,
    };
  }, [data]);

  const hasData = data.some((week) => week.avgReviewDays !== null);

  return (
    <div className="flex h-full flex-col rounded-xl border border-[var(--border)] bg-[var(--card)] p-6 shadow-sm transition-all duration-300 hover:shadow-md hover:-translate-y-1">
      <div className="mb-5 flex items-start justify-between gap-4">
        <div>
          <h2 className="text-lg font-semibold text-[var(--card-foreground)]">
            PR Review Time Trend
          </h2>
          <p className="mt-1 text-sm text-[var(--muted-foreground)]">
            Average time from PR open to merge over the last 12 weeks.
          </p>
        </div>
      </div>

      {loading ? (
        <div className="space-y-5">
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
            {[1, 2, 3].map((i) => (
              <div
                key={i}
                className="h-20 animate-pulse rounded-lg bg-[var(--card-muted)]"
              />
            ))}
          </div>
          <div className="h-[300px] animate-pulse rounded-lg bg-[var(--card-muted)]" />
          <div className="mt-4 grid grid-cols-1 gap-2 sm:grid-cols-4">
  {[1,2,3,4,5,6,7,8].map((i) => (
    <div
      key={i}
      className="h-14 rounded-md bg-[var(--card-muted)] animate-pulse"
    />
  ))}
</div>
        </div>
      ) : githubAuthInvalid ? (
        <div className="flex h-[360px] items-center justify-center">
          <div className="max-w-sm rounded-lg border border-[var(--border)] bg-[var(--background)] p-6 text-center space-y-3">
            <p className="text-sm text-[var(--muted-foreground)]">
              Your GitHub connection is no longer valid. Reconnect your GitHub
              account to continue syncing data.
            </p>
            <button
              type="button"
              onClick={() => {
                void signOut({ redirect: false }).then(() => {
                  window.location.href = "/api/auth/signin/github?callbackUrl=/dashboard";
                });
              }}
              className="inline-flex items-center rounded-lg bg-[var(--accent)] px-4 py-2 text-sm font-semibold text-white transition hover:opacity-90"
            >
              Reconnect GitHub
            </button>
          </div>
        </div>
      ) : error ? (
        <div className="flex h-[360px] items-center justify-center">
          <div className="max-w-sm rounded-lg border border-[var(--destructive)]/20 bg-[var(--destructive)]/10 p-5 text-center">
            <p className="text-sm text-[var(--destructive)]">{error}</p>
            <button
              type="button"
              onClick={fetchTrend}
              className="mt-4 rounded-md border border-[var(--destructive)]/30 px-3 py-1.5 text-xs font-medium text-[var(--destructive)] transition-colors hover:bg-[var(--destructive)]/10"
            >
              Try again
            </button>
          </div>
        </div>
      ) : !hasData ? (
        <div className="flex h-[360px] items-center justify-center rounded-lg border border-dashed border-[var(--border)]">
          <div className="text-center">
            <p className="text-sm font-medium text-[var(--card-foreground)]">
              No merged PRs found
            </p>
            <p className="mt-1 text-sm text-[var(--muted-foreground)]">
              Merged PRs are required to calculate review time.
            </p>
          </div>
        </div>
      ) : (
        <>
          <div className="mb-5 grid grid-cols-1 gap-3 sm:grid-cols-3">
            <div className="rounded-lg border border-[var(--border)] bg-[var(--background)] p-4">
              <p className="text-xs text-[var(--muted-foreground)]">
                Overall avg
              </p>
              <p className="mt-1 text-xl font-semibold text-[var(--card-foreground)]">
                {formatDays(stats.overallAvg)}
              </p>
            </div>

            <div className="rounded-lg border border-[var(--border)] bg-[var(--background)] p-4">
              <p className="text-xs text-[var(--muted-foreground)]">
                Latest week
              </p>
              <p className="mt-1 text-xl font-semibold text-[var(--card-foreground)]">
                {formatDays(stats.latestAvg)}
              </p>
            </div>

            <div className="rounded-lg border border-[var(--border)] bg-[var(--background)] p-4">
              <p className="text-xs text-[var(--muted-foreground)]">
                Merged PRs
              </p>
              <p className="mt-1 text-xl font-semibold text-[var(--card-foreground)]">
                {stats.totalMerged}
              </p>
              <p className="mt-1 text-xs text-[var(--muted-foreground)]">
                {stats.trendText}
              </p>
            </div>
          </div>

          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart
                data={data}
                margin={{ top: 16, right: 24, left: 4, bottom: 10 }}
              >
                <CartesianGrid
                  strokeDasharray="4 4"
                  stroke="var(--border)"
                  opacity={0.45}
                />

                <XAxis
  dataKey="label"
  axisLine={false}
  tickLine={false}
  tickMargin={12}
  interval="preserveStartEnd"
  tick={{ fill: "var(--muted-foreground)", fontSize: "0.7rem" }}
/>

                <YAxis
                  axisLine={false}
                  tickLine={false}
                  tickMargin={10}
                  width={48}
                  domain={[0, "dataMax + 0.5"]}
                  allowDecimals
                  tickFormatter={(value: number) => `${value}d`}
                  style={{
                    fill: "var(--muted-foreground)",
                    fontSize: "0.8rem",
                  }}
                />

                <Tooltip content={<CustomTooltip />} />

                <Line
                  type="monotone"
                  dataKey="avgReviewDays"
                  stroke="var(--accent)"
                  strokeWidth={3}
                  connectNulls={false}
                  dot={(props: any) => {
                    const point = props.payload as PRReviewTrendPoint;

                    if (point.avgReviewDays === null) {
                      return (
                        <circle
                          key={`dot-null-${props.index}`}
                          cx={props.cx}
                          cy={props.cy}
                          r={4}
                          fill="var(--muted-foreground)"
                          opacity={0.35}
                        />
                      );
                    }

                    return (
                      <circle
                        key={`dot-${props.index}`}
                        cx={props.cx}
                        cy={props.cy}
                        r={5}
                        fill="var(--accent)"
                        stroke="var(--card)"
                        strokeWidth={2}
                      />
                    );
                  }}
                  activeDot={{
                    r: 7,
                    stroke: "var(--card)",
                    strokeWidth: 2,
                  }}
                />
              </LineChart>
            </ResponsiveContainer>
          </div>

          <div className="mt-4 grid grid-cols-1 gap-2 sm:grid-cols-4">
            {data.map((week) => (
              <div
                key={week.weekStart}
                className="rounded-md border border-[var(--border)] bg-[var(--background)] px-3 py-2"
              >
                <p className="text-xs font-medium text-[var(--card-foreground)]">
                  {week.label}
                </p>
                <p className="mt-1 text-xs text-[var(--muted-foreground)]">
                  {week.avgReviewDays === null
                    ? "No merged PRs"
                    : `${formatDays(week.avgReviewDays)} · ${
                        week.mergedCount
                      } PR${week.mergedCount === 1 ? "" : "s"}`}
                </p>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";

export default function PrivacySettings() {
  const [downloading, setDownloading] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteConfirmText, setDeleteConfirmText] = useState("");
  const [message, setMessage] = useState<{ kind: "success" | "error"; text: string } | null>(null);

  /** Download a portable ZIP archive of all user-owned data. */
  async function handleExportZip() {
    setDownloading(true);
    setMessage(null);

    try {
      const res = await fetch("/api/user/export");

      if (res.status === 429) {
        const body = await res.json().catch(() => ({})) as { retryAfterSeconds?: number };
        const mins = body.retryAfterSeconds
          ? Math.ceil(body.retryAfterSeconds / 60)
          : 60;
        setMessage({
          kind: "error",
          text: `You can export once per hour. Please try again in ${mins} minute${mins === 1 ? "" : "s"}.`,
        });
        return;
      }

      if (!res.ok) {
        throw new Error("Export failed");
      }

      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `devtrack-export-${new Date().toISOString().slice(0, 10)}.zip`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      setMessage({ kind: "success", text: "Export downloaded successfully." });
    } catch {
      setMessage({ kind: "error", text: "Failed to generate export. Please try again." });
    } finally {
      setDownloading(false);
    }
  }

  async function handleDeleteAccount() {
    if (deleteConfirmText !== "DELETE") {
      setMessage({ kind: "error", text: "Please type DELETE to confirm" });
      return;
    }

    setDeleting(true);
    setMessage(null);

    try {
      const res = await fetch("/api/user/data-export", {
        method: "DELETE",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ confirmText: "DELETE" }),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error || "Failed to delete account");
      }

      window.location.href = "/api/auth/signout";
    } catch (err) {
      setMessage({
        kind: "error",
        text: err instanceof Error ? err.message : "Failed to delete account",
      });
      setDeleting(false);
    }
  }

  return (
    <div className="mt-6 rounded-xl border border-[var(--border)] bg-[var(--card)] p-6 shadow-sm transition-all duration-300 hover:shadow-md hover:-translate-y-1">
      <h2 className="text-xl font-semibold text-[var(--card-foreground)] mb-1">
        Privacy &amp; Data
      </h2>
      <p className="text-sm text-[var(--muted-foreground)] mb-6">
        Manage your data and privacy settings
      </p>

      {message && (
        <div
          className={`mb-4 rounded-lg border p-4 text-sm ${
            message.kind === "success"
              ? "border-[var(--success)]/30 bg-[var(--success)]/10 text-[var(--success)]"
              : "border-[var(--destructive)]/30 bg-[var(--destructive)]/10 text-[var(--destructive)]"
          }`}
        >
          {message.text}
        </div>
      )}

      <div className="space-y-6">
        {/* ── Export Data ──────────────────────────────────────────────────── */}
        <div>
          <h3 className="text-sm font-semibold text-[var(--card-foreground)] mb-2">
            Export Data
          </h3>
          <p className="text-sm text-[var(--muted-foreground)] mb-1">
            Download a portable ZIP archive of all your DevTrack data.
          </p>
          <p className="text-xs text-[var(--muted-foreground)] mb-4">
            Includes: profile &amp; settings, goals &amp; goal history, streak
            data, and contribution metrics. Sensitive credentials are never
            included. Rate-limited to once per hour.
          </p>

          <button
            type="button"
            onClick={handleExportZip}
            disabled={downloading}
            aria-label="Download ZIP archive of your data"
            className="inline-flex items-center gap-2 rounded-lg bg-[var(--accent)] px-4 py-2 text-sm font-medium text-[var(--accent-foreground)] transition-all duration-200 hover:opacity-90 active:scale-95 disabled:opacity-60 disabled:cursor-not-allowed"
          >
            {downloading ? (
              <>
                <svg
                  aria-hidden="true"
                  className="h-4 w-4 animate-spin"
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                >
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                  />
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"
                  />
                </svg>
                Preparing export…
              </>
            ) : (
              <>
                <svg
                  aria-hidden="true"
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-4 w-4"
                  viewBox="0 0 20 20"
                  fill="currentColor"
                >
                  <path
                    fillRule="evenodd"
                    d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z"
                    clipRule="evenodd"
                  />
                </svg>
                Download ZIP Archive
              </>
            )}
          </button>
        </div>

        {/* ── Delete Account ───────────────────────────────────────────────── */}
        <div className="border-t border-[var(--border)] pt-6">
          <h3 className="text-sm font-semibold text-[var(--card-foreground)] mb-2">
            Delete Account
          </h3>
          <p className="text-sm text-[var(--muted-foreground)] mb-4">
            Permanently delete all your data from DevTrack. This action cannot be
            undone.
          </p>

          {!showDeleteConfirm ? (
            <button
              type="button"
              onClick={() => setShowDeleteConfirm(true)}
              className="rounded-lg border border-[var(--destructive)]/30 px-4 py-2 text-sm font-medium text-[var(--destructive)] transition hover:bg-[var(--destructive)]/10"
            >
              Delete My Account
            </button>
          ) : (
            <div className="space-y-4">
              <div className="rounded-lg border border-[var(--destructive)]/30 bg-[var(--destructive)]/10 p-4">
                <p className="text-sm text-[var(--destructive)] mb-3">
                  This will permanently delete:
                </p>
                <ul className="text-xs text-[var(--muted-foreground)] space-y-1 mb-4">
                  <li>• Your account and profile</li>
                  <li>• All goals and progress data</li>
                  <li>• Metric history and snapshots</li>
                  <li>• Webhook configurations</li>
                  <li>• Linked accounts and integrations</li>
                  <li>• Local coding time data</li>
                </ul>
                <label
                  htmlFor="delete-confirm-input"
                  className="block text-sm text-[var(--destructive)] mb-3"
                >
                  Type <strong>DELETE</strong> to confirm:
                </label>
                <input
                  id="delete-confirm-input"
                  type="text"
                  value={deleteConfirmText}
                  onChange={(e) => setDeleteConfirmText(e.target.value)}
                  placeholder="Type DELETE to confirm"
                  className="w-full rounded-lg border border-[var(--destructive)]/30 bg-[var(--background)] px-3 py-2 text-sm text-[var(--foreground)] mb-3"
                />
                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={handleDeleteAccount}
                    disabled={deleting || deleteConfirmText !== "DELETE"}
                    className="rounded-lg bg-[var(--destructive)] px-4 py-2 text-sm font-medium text-[var(--accent-foreground)] transition hover:bg-[var(--destructive)]/90 disabled:opacity-60"
                  >
                    {deleting ? "Deleting..." : "Confirm Delete"}
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      setShowDeleteConfirm(false);
                      setDeleteConfirmText("");
                    }}
                    className="rounded-lg border border-[var(--border)] px-4 py-2 text-sm font-medium text-[var(--foreground)] transition hover:bg-[var(--control)]"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { Check, ChevronDown, Copy, Download, Sparkles } from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { useAccount } from "@/components/AccountContext";
import { signOut } from "next-auth/react";
import { SkeletonBlock } from "./WidgetSkeleton";

interface WeeklySummaryData {
  commits: {
    current: number;
    previous: number;
    delta: number;
    trend: "up" | "down" | "same";
  };
  prs: {
    thisWeek: { opened: number; merged: number };
    lastWeek: { opened: number; merged: number };
  };
  issues?: {
    thisWeek: { opened: number; closed: number } | number;
    lastWeek: { opened: number; closed: number } | number;
  };
  productivityScore?: {
    current: number;
    previous: number;
  };
  activeDays: { thisWeek: number; lastWeek: number };
  streak: number;
  topRepo: string | null;
}

interface AiSummaryState {
  text: string | null;
  loading: boolean;
  error: string | null;
  rateLimitReset: Date | null;
  copied: boolean;
}

export default function WeeklySummaryCard() {
  const { selectedAccount } = useAccount();
  const [summary, setSummary] = useState<WeeklySummaryData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [githubAuthInvalid, setGithubAuthInvalid] = useState(false);
  const [isCollapsed, setIsCollapsed] = useState(false);

  const [ai, setAi] = useState<AiSummaryState>({
    text: null,
    loading: false,
    error: null,
    rateLimitReset: null,
    copied: false,
  });

  const maxCommits = summary?.commits
    ? Math.max(summary.commits.current, summary.commits.previous, 1)
    : 1;

  const maxPRs = summary?.prs
    ? Math.max(summary.prs.thisWeek.merged, summary.prs.lastWeek.merged, 1)
    : 1;

  const maxActiveDays = summary?.activeDays
    ? Math.max(summary.activeDays.thisWeek, summary.activeDays.lastWeek, 1)
    : 1;

  const getIssuesCount = (val: { opened: number; closed: number } | number | undefined) => {
    if (typeof val === "number") return val;
    if (val && typeof val === "object") return val.closed;
    return 0;
  };

  const issuesThisWeek = getIssuesCount(summary?.issues?.thisWeek);
  const issuesLastWeek = getIssuesCount(summary?.issues?.lastWeek);

  const maxIssues = summary?.issues
    ? Math.max(issuesThisWeek, issuesLastWeek, 1)
    : 1;

  const fetchSummary = useCallback(() => {
    setLoading(true);
    setError(null);
    setGithubAuthInvalid(false);

    const url =
      selectedAccount !== null
        ? `/api/metrics/weekly-summary?accountId=${encodeURIComponent(selectedAccount)}`
        : "/api/metrics/weekly-summary";

    fetch(url)
      .then(async (r) => {
        const data = await r.json();
        if (data?.error === "token_expired") {
          setGithubAuthInvalid(true);
          return null;
        }
        if (!r.ok) throw new Error("API error");
        return data as WeeklySummaryData;
      })
      .then((data) => {
        if (!data) return;
        setSummary(data);
      })
      .catch(() =>
        setError(
          "We couldn't load your weekly summary right now. Please try again in a moment."
        )
      )
      .finally(() => setLoading(false));
  }, [selectedAccount]);

  useEffect(() => {
    fetchSummary();
  }, [fetchSummary]);

  const handleDownload = () => {
    if (!summary) return;

    const scoreDiff = summary.productivityScore
      ? summary.productivityScore.current - summary.productivityScore.previous
      : 0;
    const scoreSign = scoreDiff >= 0 ? "+" : "";

    const reportText = `
========================================
       WEEKLY PRODUCTIVITY REPORT
========================================

Commits This Week   : ${summary.commits.current}
Commits Last Week   : ${summary.commits.previous}
Change              : ${summary.commits.trend === "up" ? "+" : summary.commits.trend === "down" ? "-" : ""}${Math.abs(summary.commits.delta)}

PRs Opened          : ${summary.prs.thisWeek.opened}
PRs Merged          : ${summary.prs.thisWeek.merged}
${summary.issues ? `\nIssues Resolved     : ${issuesThisWeek}
Issues Last Week    : ${issuesLastWeek}` : ""}

Active Days         : ${summary.activeDays.thisWeek} / 7
Current Streak      : ${summary.streak} days
Top Repository      : ${summary.topRepo ?? "-"}
${summary.productivityScore ? `\nProductivity Score  : ${summary.productivityScore.current} (${scoreSign}${scoreDiff} vs last week)` : ""}
${ai.text ? `\nAI Summary\n----------\n${ai.text}` : ""}

========================================
    `.trim();

    const blob = new Blob([reportText], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "weekly-summary-report.txt";
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleGenerateSummary = useCallback(() => {
    if (!summary || ai.loading) return;

    setAi((prev) => ({ ...prev, loading: true, error: null }));

    fetch("/api/ai/weekly-summary", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        commits: summary.commits,
        prs: summary.prs,
        streak: summary.streak,
        topRepo: summary.topRepo,
        activeDays: summary.activeDays,
      }),
    })
      .then(async (r) => {
        const body = await r.json();
        if (r.status === 429) {
          const resetDate = body.rateLimitReset
            ? new Date(body.rateLimitReset)
            : null;
          setAi((prev) => ({
            ...prev,
            loading: false,
            error: null,
            rateLimitReset: resetDate,
          }));
          return;
        }
        if (!r.ok) {
          setAi((prev) => ({
            ...prev,
            loading: false,
            error: body.error ?? "Failed to generate summary",
          }));
          return;
        }
        setAi((prev) => ({
          ...prev,
          loading: false,
          error: null,
          rateLimitReset: body.rateLimitReset
            ? new Date(body.rateLimitReset)
            : null,
          text: body.summary ?? null,
        }));
      })
      .catch(() => {
        setAi((prev) => ({
          ...prev,
          loading: false,
          error: "Could not reach the summary service. Please try again.",
        }));
      });
  }, [summary, ai.loading]);

  const handleCopy = useCallback(() => {
    if (!ai.text) return;
    navigator.clipboard.writeText(ai.text).then(() => {
      setAi((prev) => ({ ...prev, copied: true }));
      setTimeout(() => setAi((prev) => ({ ...prev, copied: false })), 2000);
    });
  }, [ai.text]);

  const rateLimitMessage = (() => {
    if (!ai.rateLimitReset) return null;
    const now = Date.now();
    const resetMs = ai.rateLimitReset.getTime() - now;
    if (resetMs <= 0) return null;
    const hours = Math.floor(resetMs / 3_600_000);
    const minutes = Math.floor((resetMs % 3_600_000) / 60_000);
    if (hours > 0) {
      return `Summary already generated today. Next available in ${hours}h ${minutes}m.`;
    }
    return `Summary already generated today. Next available in ${minutes}m.`;
  })();

  return (
    <div className="rounded-xl border border-[var(--border)] bg-[var(--card)] p-6 shadow-sm">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold text-[var(--card-foreground)]">
          This Week
        </h2>
        <div className="flex items-center gap-2">
          {summary && !loading && !ai.text && !ai.loading && !rateLimitMessage && (
            <button
              type="button"
              onClick={handleGenerateSummary}
              className="flex items-center gap-1 rounded-md px-2 py-1 text-xs font-medium text-[var(--muted-foreground)] transition-colors hover:bg-[var(--control)] hover:text-[var(--card-foreground)]"
              aria-label="Generate AI summary"
              title="Generate AI summary"
            >
              <Sparkles className="h-3.5 w-3.5" />
              <span>Summarise</span>
            </button>
          )}
          {summary && (
            <button
              type="button"
              onClick={handleDownload}
              className="text-sm text-[var(--muted-foreground)] transition-colors hover:text-[var(--card-foreground)]"
              aria-label="Download weekly report"
              title="Download weekly report"
            >
              <Download className="h-4 w-4" />
            </button>
          )}
          <button
            type="button"
            onClick={() => setIsCollapsed((value) => !value)}
            className="text-sm text-[var(--muted-foreground)] transition-colors hover:text-[var(--card-foreground)]"
            aria-expanded={!isCollapsed}
            aria-label={
              isCollapsed ? "Expand weekly summary" : "Collapse weekly summary"
            }
            suppressHydrationWarning
          >
            <ChevronDown className="h-4 w-4" />
          </button>
        </div>
      </div>

      {!isCollapsed &&
        (loading ? (
          <div
            role="status"
            aria-live="polite"
            aria-busy="true"
            className="mt-4 space-y-3"
          >
            <span className="sr-only">Loading weekly summary</span>
            {[1, 2, 3, 4, 5].map((i) => (
              <SkeletonBlock key={i} className="h-20 rounded-lg" />
            ))}
          </div>
        ) : githubAuthInvalid ? (
          <div className="mt-4 rounded-lg border border-[var(--border)] bg-[var(--background)] p-6 text-center space-y-3">
            <p className="text-sm text-[var(--muted-foreground)]">
              Your GitHub connection is no longer valid. Reconnect your GitHub
              account to continue syncing data.
            </p>
            <button
              type="button"
              onClick={() => {
                void signOut({ redirect: false }).then(() => {
                  window.location.href = "/api/auth/signin/github?callbackUrl=/dashboard";
                });
              }}
              className="inline-flex items-center rounded-lg bg-[var(--accent)] px-4 py-2 text-sm font-semibold text-white transition hover:opacity-90"
            >
              Reconnect GitHub
            </button>
          </div>
        ) : error ? (
          <div className="mt-4 rounded-lg border border-[var(--destructive)]/20 bg-[var(--destructive)]/10 p-4 text-sm text-[var(--destructive)]">
            {error}
          </div>
        ) : summary &&
          summary.commits &&
          summary.prs &&
          summary.activeDays ? (
          <div className="mt-4 space-y-4">
            {ai.loading && (
              <div
                role="status"
                aria-live="polite"
                aria-busy="true"
                className="flex items-center gap-2 rounded-lg bg-[var(--control)] p-4"
              >
                <Sparkles className="h-4 w-4 animate-pulse text-[var(--muted-foreground)]" />
                <span className="text-sm text-[var(--muted-foreground)]">
                  Generating summary...
                </span>
              </div>
            )}

            {ai.error && !ai.loading && (
              <div className="rounded-lg border border-[var(--destructive)]/20 bg-[var(--destructive)]/10 p-4 text-sm text-[var(--destructive)]">
                {ai.error}
              </div>
            )}

            {rateLimitMessage && !ai.loading && (
              <div className="rounded-lg border border-[var(--border)] bg-[var(--control)] p-4 text-sm text-[var(--muted-foreground)]">
                {rateLimitMessage}
              </div>
            )}

            {ai.text && !ai.loading && (
              <div className="rounded-lg border border-[var(--border)] bg-[var(--control)] p-4">
                <div className="mb-2 flex items-center justify-between">
                  <span className="flex items-center gap-1.5 text-xs font-medium text-[var(--muted-foreground)]">
                    <Sparkles className="h-3.5 w-3.5" />
                    AI Summary
                  </span>
                  <button
                    type="button"
                    onClick={handleCopy}
                    className="flex items-center gap-1 rounded px-1.5 py-0.5 text-xs text-[var(--muted-foreground)] transition-colors hover:bg-[var(--border)] hover:text-[var(--card-foreground)]"
                    aria-label="Copy AI summary to clipboard"
                    title="Copy to clipboard"
                  >
                    {ai.copied ? (
                      <>
                        <Check className="h-3 w-3 text-[var(--success)]" />
                        <span className="text-[var(--success)]">Copied</span>
                      </>
                    ) : (
                      <>
                        <Copy className="h-3 w-3" />
                        <span>Copy</span>
                      </>
                    )}
                  </button>
                </div>
                <p className="text-sm leading-relaxed text-[var(--card-foreground)]">
                  {ai.text}
                </p>
              </div>
            )}

            {/* Commits Comparison */}
            <div className="rounded-lg bg-[var(--control)] p-4">
              <div className="mb-3 flex items-center justify-between">
                <span className="text-sm text-[var(--muted-foreground)]">
                  Commits
                </span>
                <span className="text-base font-semibold text-[var(--card-foreground)]">
                  {summary.commits.current}
                  {summary.commits.trend !== "same" && (
                    <span
                      className="ml-2 text-sm font-medium"
                      style={{
                        color:
                          summary.commits.trend === "up"
                            ? "var(--success)"
                            : "var(--destructive)",
                      }}
                    >
                      {summary.commits.trend === "up" ? "+" : "-"}
                      {Math.abs(summary.commits.delta)}
                    </span>
                  )}
                </span>
              </div>
              <div className="space-y-1.5">
                <div className="flex items-center gap-2">
                  <span className="w-16 text-xs text-[var(--muted-foreground)]">
                    Last week
                  </span>
                  <div className="flex-1">
                    <div className="h-2 overflow-hidden rounded bg-[var(--border)]">
                      <div
                        className="h-full bg-[var(--muted-foreground)]"
                        style={{
                          width: `${((summary.commits.previous / maxCommits) * 100).toFixed(0)}%`,
                        }}
                      />
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <span className="w-16 text-xs text-[var(--muted-foreground)]">
                    This week
                  </span>
                  <div className="flex-1">
                    <div className="h-2 overflow-hidden rounded bg-[var(--border)]">
                      <div
                        className="h-full bg-[var(--success)]"
                        style={{
                          width: `${((summary.commits.current / maxCommits) * 100).toFixed(0)}%`,
                        }}
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* PRs Comparison */}
            <div className="rounded-lg bg-[var(--control)] p-4">
              <div className="mb-3 flex items-center justify-between">
                <span className="text-sm text-[var(--muted-foreground)]">
                  PRs Merged
                </span>
                <span className="text-base font-semibold text-[var(--card-foreground)]">
                  {summary.prs.thisWeek.merged}
                </span>
              </div>
              <div className="space-y-1.5">
                <div className="flex items-center gap-2">
                  <span className="w-16 text-xs text-[var(--muted-foreground)]">
                    Last week
                  </span>
                  <div className="flex-1">
                    <div className="h-2 overflow-hidden rounded bg-[var(--border)]">
                      <div
                        className="h-full bg-[var(--muted-foreground)]"
                        style={{
                          width: `${((summary.prs.lastWeek.merged / maxPRs) * 100).toFixed(0)}%`,
                        }}
                      />
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <span className="w-16 text-xs text-[var(--muted-foreground)]">
                    This week
                  </span>
                  <div className="flex-1">
                    <div className="h-2 overflow-hidden rounded bg-[var(--border)]">
                      <div
                        className="h-full bg-[var(--success)]"
                        style={{
                          width: `${((summary.prs.thisWeek.merged / maxPRs) * 100).toFixed(0)}%`,
                        }}
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Issues Resolved */}
            {summary.issues && (
              <div className="rounded-lg bg-[var(--control)] p-4">
                <div className="mb-3 flex items-center justify-between">
                  <span className="text-sm text-[var(--muted-foreground)]">
                    Issues Resolved
                  </span>
                  <span className="text-base font-semibold text-[var(--card-foreground)]">
                    {issuesThisWeek}
                  </span>
                </div>
                <div className="space-y-1.5">
                  <div className="flex items-center gap-2">
                    <span className="w-16 text-xs text-[var(--muted-foreground)]">
                      Last week
                    </span>
                    <div className="flex-1">
                      <div className="h-2 overflow-hidden rounded bg-[var(--border)]">
                        <div
                          className="h-full bg-[var(--muted-foreground)] opacity-50 rounded-full transition-all duration-500 ease-out"
                          style={{
                            width: `${((issuesLastWeek / maxIssues) * 100).toFixed(0)}%`,
                          }}
                        />
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="w-16 text-xs text-[var(--muted-foreground)]">
                      This week
                    </span>
                    <div className="flex-1">
                      <div className="h-2 overflow-hidden rounded bg-[var(--border)]">
                        <div
                          className="h-full bg-[var(--success)]"
                          style={{
                            width: `${((issuesThisWeek / maxIssues) * 100).toFixed(0)}%`,
                          }}
                        />
                      </div>
                    </div>
                  </div>
                </div>
              </div>

            )}

            {/* Active Days Comparison */}
            <div className="rounded-lg bg-[var(--control)] p-4">
              <div className="mb-3 flex items-center justify-between">
                <span className="text-sm text-[var(--muted-foreground)]">
                  Active Days
                </span>
                <span className="text-base font-semibold text-[var(--card-foreground)]">
                  {summary.activeDays.thisWeek} / 7
                </span>
              </div>
              <div className="space-y-1.5">
                <div className="flex items-center gap-2">
                  <span className="w-16 text-xs text-[var(--muted-foreground)]">
                    Last week
                  </span>
                  <div className="flex-1">
                    <div className="h-2 overflow-hidden rounded bg-[var(--border)]">
                      <div
                        className="h-full bg-[var(--muted-foreground)]"
                        style={{
                          width: `${((summary.activeDays.lastWeek / maxActiveDays) * 100).toFixed(0)}%`,
                        }}
                      />
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <span className="w-16 text-xs text-[var(--muted-foreground)]">
                    This week
                  </span>
                  <div className="flex-1">
                    <div className="h-2 overflow-hidden rounded bg-[var(--border)]">
                      <div
                        className="h-full bg-[var(--success)]"
                        style={{
                          width: `${((summary.activeDays.thisWeek / maxActiveDays) * 100).toFixed(0)}%`,
                        }}
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Productivity Score */}
            {summary.productivityScore && (
              <div className="rounded-lg bg-[var(--control)] p-4">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-[var(--muted-foreground)]">
                    Productivity Score
                  </span>
                  <span className="text-base font-semibold text-[var(--card-foreground)]">
                    {summary.productivityScore.current}
                    <span
                      className="ml-2 text-sm font-medium"
                      style={{
                        color:
                          summary.productivityScore.current >=
                          summary.productivityScore.previous
                            ? "var(--success)"
                            : "var(--destructive)",
                      }}
                    >
                      {summary.productivityScore.current >=
                      summary.productivityScore.previous
                        ? "+"
                        : ""}
                      {summary.productivityScore.current -
                        summary.productivityScore.previous}{" "}
                      vs last week
                    </span>
                  </span>
                </div>
              </div>
            )}

            {/* Streak & Top Repo */}
            <div className="space-y-3">
              <div className="flex items-center justify-between rounded-lg bg-[var(--control)] p-4">
                <span className="text-sm text-[var(--muted-foreground)]">
                  Streak
                </span>
                <span className="text-base font-semibold text-[var(--card-foreground)]">
                  {summary.streak} day streak
                </span>
              </div>
              <div className="flex items-center justify-between rounded-lg bg-[var(--control)] p-4">
                <span className="text-sm text-[var(--muted-foreground)]">
                  Top repo
                </span>
                <span className="text-base font-semibold text-[var(--card-foreground)]">
                  {summary.topRepo ?? "-"}
                </span>
              </div>
            </div>
          </div>
        ) : null)}
    </div>
  );
}
